// Additional tools share the studio's IndexedDB and complete encrypted-backup transport.
const MG=MotiveGrowth;
function validateGrowthPayload(row){
 const p=row.payload;const str=(v,n)=>typeof v==='string'&&v.length>0&&v.length<=n;
 const mood=()=>str(p.label,35)&&str(p.icon,8)&&/^#[a-f\d]{6}$/i.test(p.color);
 let valid=false;
 switch(row.kind){
  case 'habit':valid=str(p.title,80)&&['daily','weekly','monthly'].includes(p.cadence)&&Number.isInteger(p.target)&&p.target>=1&&p.target<=31;break;
  case 'habit-log':valid=str(p.habit,120)&&MG.validDay(p.day);break;
  case 'mood-label':valid=mood();break;
  case 'mood':valid=mood()&&MG.validDay(p.day)&&Array.isArray(p.activities)&&p.activities.length<=10&&p.activities.every(x=>str(x,40));break;
  case 'quote-tags':valid=(typeof p.quote==='string'||Number.isInteger(p.quote))&&Array.isArray(p.tags)&&p.tags.length<=10&&p.tags.every(t=>str(t,40));break;
  case 'narration':valid=str(p.title,100)&&safeMedia(p.audio,'audio/');break;
  case 'movement':valid=str(p.title,100)&&safeMedia(p.video,'video/');break;
 }
 if(!valid)throw Error('Invalid daily practice record in backup.');
}
function remapGrowthTags(rows,backup,merged){
 const incoming=backup?.data?.custom||[];const available=[...reminders,...merged.custom];
 for(const row of rows.filter(r=>r.kind==='quote-tags'&&r.payload)){
  const original=incoming.find(q=>q.id===row.payload.quote);if(!original)continue;
  const target=available.find(q=>quoteKey(q.text)===quoteKey(original.text));if(target)row.payload={...row.payload,quote:target.id};
 }
}
