const growthEntry=document.createElement('button');growthEntry.className='outline-button';growthEntry.id='growth-button';growthEntry.textContent='Your daily practice →';studioEntry.append(growthEntry);
function growthMessage(id,message){$(id).textContent=message;}
function growthButton(text,action){const b=document.createElement('button');b.className='text-button';b.textContent=text;b.onclick=async()=>{b.disabled=true;try{await action();}catch(e){toast(e.message);}finally{b.disabled=false;}};return b;}
function growthCard(title,note=''){const a=document.createElement('article');a.className='studio-record';const h=document.createElement('h4');h.textContent=title;a.append(h);if(note){const p=document.createElement('p');p.textContent=note;a.append(p);}return a;}
async function openGrowth(page=0){try{studioRecords=await dbRead();await archiveLegacyMoods();growthDialog.showModal();if(typeof refreshMotiveNavigation==='function')refreshMotiveNavigation();showGrowth(page);}catch(e){toast(e.message);}}
function showGrowth(page){stopSleep();stopMovement();growthPage=page;for(let i=0;i<7;i++){$('growth-'+i).hidden=i!==page;$('growth-nav-'+i).setAttribute('aria-pressed',String(i===page));}if(page===0)renderToday();if(page===1)renderHabits();if(page===2)renderMoods();if(page===3)renderTags();if(page===4){renderStory();renderNarration();}if(page===5)renderMovementVideos();}
$('growth-button').onclick=()=>openGrowth();$('growth-close').onclick=()=>growthDialog.close();for(let i=0;i<7;i++)$('growth-nav-'+i).onclick=()=>showGrowth(i);
function growthRows(kind){return (typeof studioReadableRows==='function'?studioReadableRows():studioRecords).filter(r=>r.kind===kind&&!r.deleted&&r.payload);}
function dayDate(){return dayKey();}

let motiveTodayLocaleReplay=false,motiveRecommendationSource=null,motiveFocusPresentation=null;
const motiveReviewedRecommendations=[{"tool": "sleep", "title": "An easier landing tonight", "reason": "It is late in your local day. A quiet story or a sleep timer may fit.", "kind": "quiet"}, {"tool": "calm", "title": "Start with the room around you", "reason": "Your latest check-in suggests a short grounding pause. No breathing count is needed.", "kind": "ground"}, {"tool": "focus", "title": "Protect one small piece of attention", "reason": "Your focus goal can start with a short, clearly bounded task.", "kind": "even"}, {"tool": "journey", "title": "Keep one small promise to yourself", "reason": "Your confidence goal fits the seven-step Confidence journey. Start wherever you are.", "kind": "Confidence"}, {"tool": "calm", "title": "A one-minute pause is enough", "reason": "This fits the time you chose today.", "kind": "body"}, {"tool": "calm", "title": "Return to a gentle pause", "reason": "Based on your available time and completed sessions. You can always choose something else.", "kind": "settle"}, {"tool": "calm", "title": "Try a comfortable first pause", "reason": "Based on your available time and completed sessions. You can always choose something else.", "kind": "settle"}];
function renderMotiveRecommendation(rec=motiveRecommendationSource){if(!rec)return;if(rec!==motiveRecommendationSource)motiveRecommendationSource={...rec};const reviewed=motiveReviewedRecommendations.some(r=>['tool','title','reason','kind'].every(k=>r[k]===rec[k]));for(const [id,key]of [['recommend-title','title'],['recommend-reason','reason']]){const shown=reviewed?appInterface(rec[key]):{text:rec[key],language:'en'};$(id).textContent=shown.text;$(id).setAttribute('lang',shown.language);}}
const motiveFocusMessages=new Set(['Your focus time is complete. Take a comfortable break.','You can begin again whenever it helps.','Your rounds are complete. Take a comfortable pause.','Choose focus 1–120 minutes, breaks 1–30, and 1–8 rounds.']);
function renderMotiveFocusStatus(){const frame=motiveFocusPresentation;if(!frame)return;let shown;if(frame.kind==='task'){shown=appInterface('{time} · {task}',{time:WB.clock(frame.seconds),task:frame.task||appInterface('One small thing').text});}else if(frame.kind==='cycle'){const source=frame.phase==='focus'?'Focus · round {round} of {total} · {time}':'Break · round {round} of {total} · {time}';shown=appInterface(source,{round:frame.round,total:frame.total,time:WB.clock(frame.seconds)});}else shown=motiveFocusMessages.has(frame.source)?appInterface(frame.source):{text:frame.source,language:'en'};$('focus-status').textContent=shown.text;$('focus-status').setAttribute('lang',shown.language);}
function showMotiveFocusTask(seconds,task){motiveFocusPresentation={kind:'task',seconds,task};renderMotiveFocusStatus();}
function showMotiveFocusCycle(phase,round,total,seconds){motiveFocusPresentation={kind:'cycle',phase,round,total,seconds};renderMotiveFocusStatus();}

function recommendationNow(){const latest=moodEntries().at(-1);return MG.recommendation({mood:latest?.key||defaultMoods.find(m=>m.label===latest?.label)?.id,goal:$('growth-goal').value,minutes:Number($('growth-minutes').value)||3,sessions:studioPrefs.sessions?.length||0,hour:new Date().getHours()});}
function renderToday(){const rec=motiveTodayLocaleReplay&&motiveRecommendationSource?motiveRecommendationSource:recommendationNow();renderMotiveRecommendation(rec);const daily=MG.dailyMeditation(dayDate());growthMessage('daily-meditation-title',daily.title+' · today');growthMessage('daily-meditation-preview',daily.steps[0]);}
function growthSession(kind){growthDialog.close();$('session-kind').value=kind;$('session-minutes').value=$('growth-minutes').value||'3';openStudio('calm');}
$('growth-goal').onchange=$('growth-minutes').onchange=()=>renderToday();
$('recommend-open').onclick=()=>{const rec=recommendationNow();if(rec.tool==='sleep')showGrowth(4);else if(rec.tool==='journey'){growthDialog.close();$('journey-theme').value='Confidence';openStudio('journeys');}else if(rec.tool==='focus')$('focus-task').focus();else growthSession(rec.kind);};
WB.sessions.daily=MG.dailyMeditation(dayDate());const dailyOption=document.createElement('option');dailyOption.value='daily';dailyOption.textContent="Today's original guided pause";$('session-kind').append(dailyOption);
$('daily-meditation-open').onclick=()=>{WB.sessions.daily=MG.dailyMeditation(dayDate());growthSession('daily');};
function stopFocus(){clearInterval(focusTimer);focusTimer=null;focusDeadline=0;$('focus-start').disabled=false;}
function tickFocus(){if(!focusDeadline)return;const seconds=Math.max(0,Math.ceil((focusDeadline-Date.now())/1000));if(seconds)showMotiveFocusTask(seconds,$('focus-task').value.trim());else growthMessage('focus-status','Your focus time is complete. Take a comfortable break.');if(!seconds)stopFocus();}
$('focus-start').onclick=()=>{stopFocus();focusDeadline=Date.now()+Math.min(25,Math.max(1,Number($('focus-length').value)||10))*60000;$('focus-start').disabled=true;tickFocus();focusTimer=setInterval(tickFocus,1000);};$('focus-stop').onclick=()=>{stopFocus();growthMessage('focus-status','You can begin again whenever it helps.');};
async function addHabit(){const title=$('habit-name').value.trim();const target=Number($('habit-target').value);if(!title||!Number.isInteger(target)||target<1||target>31)throw Error('Give your habit a name and a target from 1 to 31.');const cadence=$('habit-cadence').value;if(!['daily','weekly','monthly'].includes(cadence))throw Error('Choose a repeat period.');await dbWrite([newRecord('habit',{title,cadence,target})]);$('habit-name').value='';renderHabits();growthMessage('habit-status','Habit added. Keep it small enough to fit your day.');}
$('habit-add').onclick=()=>addHabit().catch(e=>growthMessage('habit-status',e.message));
function renderHabits(){const host=$('habit-list');host.replaceChildren();for(const row of growthRows('habit')){const h={...row.payload,id:row.id};const count=MG.habitCount(h,growthRows('habit-log'),dayDate());const card=growthCard(h.title,`${count} of ${h.target} · ${h.cadence}`);card.append(growthButton('Mark one done',async()=>{await dbWrite([newRecord('habit-log',{habit:row.id,day:dayDate()})]);renderHabits();}),growthButton('Undo today’s last mark',async()=>{const log=growthRows('habit-log').filter(r=>r.payload.habit===row.id&&r.payload.day===dayDate()).sort((a,b)=>b.updated-a.updated)[0];if(log)await dbWrite([{...log,deleted:true,updated:Date.now()}]);renderHabits();}),growthButton('Archive habit',async()=>{await dbWrite([{...row,deleted:true,updated:Date.now()}]);renderHabits();}));host.append(card);}if(!host.children.length)host.append(growthCard('Start with one small habit','Choose daily, weekly, or monthly.'))}
const defaultMoods=[{id:'low',label:'Low energy',icon:'◒',color:'#a7b5cf'},{id:'scattered',label:'Scattered',icon:'✧',color:'#d4b47c'},{id:'stuck',label:'Stuck',icon:'◈',color:'#c6a7b5'},{id:'curious',label:'Curious',icon:'✳',color:'#83b29c'},{id:'overwhelmed',label:'Overwhelmed',icon:'≈',color:'#b9a0cf'}];
function moodsAvailable(){return [...defaultMoods,...growthRows('mood-label').map(r=>({...r.payload,id:r.id}))];}
async function archiveLegacyMoods(){const rows=[];for(const [day,e]of Object.entries(state.companion.journal)){const m=defaultMoods.find(m=>m.id===e.mood);if(m&&!studioRecords.some(r=>r.id==='mood-'+day))rows.push({id:'mood-'+day,kind:'mood',updated:0,payload:{day,key:m.id,label:m.label,icon:m.icon,color:m.color,activities:[]}});}if(rows.length)await dbWrite(rows);}
const originalChooseArrival=chooseArrival;chooseArrival=function(key){originalChooseArrival(key);const m=defaultMoods.find(m=>m.id===key);if(!m)return;const day=dayDate();const previous=growthRows('mood').find(r=>r.id==='mood-'+day);dbWrite([{id:'mood-'+day,kind:'mood',updated:Date.now(),payload:{day,key:m.id,label:m.label,icon:m.icon,color:m.color,activities:previous?.payload.activities||[]}}]).catch(e=>toast(e.message));};
function moodEntries(){const map=new Map();for(const [day,entry]of Object.entries(state.companion.journal)){const mood=defaultMoods.find(m=>m.id===entry.mood);if(mood)map.set(day,{day,...mood,activities:[]});}for(const r of growthRows('mood').sort((a,b)=>a.updated-b.updated))map.set(r.payload.day,r.payload);return [...map.values()].sort((a,b)=>a.day.localeCompare(b.day));}
$('mood-day').value=dayDate();$('mood-month').value=dayDate().slice(0,7);
// Mood presentation uses reviewed identities; custom words never become message keys.
const motiveMoodDays=new WeakMap();
function motiveMoodLabel(entry){const source=motiveJournalMood(entry);return source?appInterface(source):{text:entry.label,language:'en'};}
function motiveMoodLabelNode(entry){const source=motiveJournalMood(entry);if(source)return motiveJournalWord('span',source);const node=document.createElement('span');node.textContent=entry.label;return node;}
function refreshMotiveMoodCalendar(node){const language=['es','fr'].includes(studioPrefs.language)?studioPrefs.language:'en';if(node.dataset.motiveMoodMonth){node.textContent=new Date(node.dataset.motiveMoodMonth+'-15T12:00:00').toLocaleDateString(language==='es'?'es-ES':language==='fr'?'fr-FR':'en-US',{month:'long',year:'numeric'});node.setAttribute('lang',language);}else if(node.dataset.motiveMoodWeekday!==undefined){const letters={en:['M','T','W','T','F','S','S'],es:['L','M','X','J','V','S','D'],fr:['L','M','M','J','V','S','D']};node.textContent=letters[language][Number(node.dataset.motiveMoodWeekday)];node.setAttribute('lang',language);}else{const info=motiveMoodDays.get(node);if(!info)return;const label=info.entry?motiveMoodLabel(info.entry):appInterface('No check-in');node.setAttribute('aria-label',info.day+' · '+label.text);node.title=info.day+' · '+label.text;node.setAttribute('lang',label.language);}}
function showMotiveMoodDay(day,entry){$('mood-day').value=day;const host=$('mood-status');delete host.dataset.motiveMoodStatus;host.replaceChildren(document.createTextNode(day+' · '));host.setAttribute('lang','en');if(entry){host.append(document.createTextNode(entry.icon+' '),motiveMoodLabelNode(entry));if(entry.activities?.length)host.append(document.createTextNode(' · '+entry.activities.join(', ')));}else host.append(motiveJournalWord('span','No check-in'));}
