function renderTags(){motiveTagQuoteText($('tag-quote'),current);const existing=growthRows('quote-tags').find(r=>r.payload.quote===current.id),saved=(existing?.payload.tags||[]).join(', '),field=$('quote-tags');if(motiveTagEditorId!==current.id||field.value===motiveTagEditorSource)field.value=saved;motiveTagEditorId=current.id;motiveTagEditorSource=saved;const query=$('tag-filter').value.trim().toLocaleLowerCase(),quotes=allQuotes();const rows=growthRows('quote-tags').filter(r=>r.payload.tags.some(t=>t.toLocaleLowerCase().includes(query))&&quotes.some(q=>q.id===r.payload.quote));const host=$('tag-results');host.replaceChildren();let count=0;for(const r of rows.slice(0,tagLimit)){const q=quotes.find(q=>q.id===r.payload.quote),card=growthCard(r.payload.tags.join(' · ')),words=document.createElement('p');motiveTagQuoteText(words,q);card.append(words,motiveJournalAction('Read this quote',()=>{growthDialog.close();showQuote(q,{revisit:true});}));host.append(card);count++;}if(!count)host.append(motiveJournalPublicCard('No matching tagged quotes','Save tags for a quote, or try a different tag.'));$('tag-results-status').replaceChildren(motiveJournalWord('span','Tagged quotes shown: {count}.',{count}));$('tag-more').hidden=rows.length<=tagLimit;}
