function stopSleep(){clearInterval(sleepTimer);sleepTimer=null;sleepDeadline=0;if(sleepAudio){sleepAudio.pause();sleepAudio.onended=null;sleepAudio=null;}stopSpeech();$('sleep-start').disabled=false;}
function checkSleep(){if(!sleepDeadline)return false;if(document.hidden||Date.now()>=sleepDeadline){stopSleep();growthMessage('sleep-status','Sleep audio stopped. Rest at your own pace.');return false;}growthMessage('sleep-status','Stops in '+WB.clock(Math.max(0,Math.ceil((sleepDeadline-Date.now())/1000))));return true;}
function beginSleepTimer(){sleepDeadline=Date.now()+Math.min(60,Math.max(1,Number($('sleep-length').value)||15))*60000;sleepTimer=setInterval(checkSleep,1000);$('sleep-start').disabled=true;checkSleep();}
function readSleepStory(){if(!checkSleep())return;const story=MG.stories.find(s=>s.id===$('sleep-story').value)||MG.stories[0];speakWords(story.text,()=>{if(checkSleep()&&$('sleep-repeat').checked)readSleepStory();else if(sleepDeadline){stopSleep();growthMessage('sleep-status','Story complete.');}},'en');}
$('sleep-start').onclick=()=>{stopSleep();if(!('speechSynthesis'in window)){growthMessage('sleep-status','Device speech is unavailable. You can read the story or import audio.');return;}beginSleepTimer();readSleepStory();};$('sleep-stop').onclick=()=>{stopSleep();growthMessage('sleep-status','Audio stopped.');};
async function importMedia(kind,input,status){try{const file=$(input).files[0];if(!file)throw Error('Choose a file first.');if(file.size>12*1024*1024)throw Error('Choose a file up to 12 MB.');const prefix=kind==='narration'?'audio/':'video/';if(!file.type.startsWith(prefix))throw Error('Choose a supported '+prefix.slice(0,-1)+' file.');const data=await fileData(file);if(!safeMedia(data,prefix))throw Error('This file format is not supported.');const title=kind==='narration'?$('narration-title').value.trim()||file.name:file.name;await dbWrite([newRecord(kind,{title:title.slice(0,100),[kind==='narration'?'audio':'video']:data})]);$(input).value='';growthMessage(status,'Saved on this device. Include it in a full backup.');renderNarration();renderMovementVideos();}catch(e){growthMessage(status,e.message);}}
$('narration-import').onclick=()=>importMedia('narration','narration-file','narration-status');$('movement-import').onclick=()=>importMedia('movement','movement-file','movement-status');
function renderNarration(){const host=$('narration-list');host.replaceChildren();for(const r of growthRows('narration')){const card=growthCard(r.payload.title);card.append(motiveJournalAction('Play with sleep timer',async()=>{stopSleep();sleepAudio=new Audio(r.payload.audio);if(typeof configureMotiveMedia==='function')configureMotiveMedia(sleepAudio);sleepAudio.loop=$('sleep-repeat').checked;beginSleepTimer();sleepAudio.onended=()=>{stopSleep();growthMessage('sleep-status','Recording complete.');};try{await sleepAudio.play();}catch{stopSleep();growthMessage('sleep-status','Could not play this recording. Try another audio format.');}}),motiveJournalAction('Remove recording',async()=>{stopSleep();await dbWrite([{id:r.id,kind:r.kind,updated:Date.now(),deleted:true}]);renderNarration();}));host.append(card);}}

const motiveReviewedMovements=[{"id": "hands", "title": "Rest your hands", "seconds": 45, "steps": ["Sit or stand somewhere steady. Rest your forearms comfortably.", "Open and close your hands slowly, only through a comfortable range.", "Let your hands rest again. Stillness is an equally good option."]}, {"id": "shoulders", "title": "A small shoulder reset", "seconds": 60, "steps": ["Find a supported position. Let your arms rest by your sides.", "Gently lift your shoulders a little, then let them return. Keep the motion easy.", "Pause between movements. Stop if anything hurts or feels uncomfortable."]}, {"id": "break", "title": "An easy screen break", "seconds": 60, "steps": ["Look away from the screen toward something at a comfortable distance.", "If it suits you, stand near a stable support or remain seated and change position.", "Notice the room, then return slowly when you are ready."]}];
