function motiveMovementPresentation(routine){const reviewed=motiveReviewedMovements.find(r=>r.id===routine.id),matches=reviewed&&reviewed.title===routine.title&&reviewed.seconds===routine.seconds&&Array.isArray(routine.steps)&&JSON.stringify(reviewed.steps)===JSON.stringify(routine.steps);return matches?{title:appInterface(routine.title),steps:routine.steps.map(s=>appInterface(s))}:{title:{text:routine.title,language:'en'},steps:(routine.steps||[]).map(text=>({text,language:'en'}))};}
function renderMotiveMovementStep(){if(!motiveMovementStep)return;const {routine,index}=motiveMovementStep,current=MG.movements.find(r=>r.id===routine.id),source=current&&JSON.stringify(current)===JSON.stringify(routine)?current:routine,presentation=current===source?motiveMovementPresentation(source):{steps:routine.steps.map(text=>({text,language:'en'}))},shown=presentation.steps[index];if(!shown)return;const node=$('movement-words');node.textContent=shown.text;node.setAttribute('lang',shown.language);}
function showMotiveMovementStep(routine,index){motiveMovementStep={routine:{id:routine.id,title:routine.title,seconds:routine.seconds,steps:[...routine.steps]},index};delete $('movement-words').dataset.motiveMovementSource;renderMotiveMovementStep();}
const motiveMovementOptions=new WeakMap();
function renderMotiveMovementOptions(){for(const option of Array.from($('movement-kind')?.options||[])){const routine=MG.movements.find(r=>r.id===option.value);if(!routine)continue;if(!motiveMovementOptions.has(option)){if(option.textContent!==routine.title+' · '+routine.seconds+' seconds')continue;motiveMovementOptions.set(option,routine.id);}const shown=motiveMovementPresentation(routine),caption=appInterface('{title} · {seconds} seconds',{title:shown.title.text,seconds:routine.seconds});option.textContent=caption.text;option.setAttribute('lang',shown.title.language==='en'?'en':caption.language);if(shown.title.language==='en')option.textContent=routine.title+' · '+routine.seconds+' seconds';}}

