$('movement-start').onclick=()=>{stopMovement();const routine=MG.movements.find(m=>m.id===$('movement-kind').value)||MG.movements[0];const start=performance.now();$('movement-start').disabled=true;$('movement-figure').classList.add('moving');const tick=()=>{const elapsed=(performance.now()-start)/1000;const remaining=Math.max(0,Math.ceil(routine.seconds-elapsed));growthMessage('movement-clock',WB.clock(remaining));showMotiveMovementStep(routine,Math.min(routine.steps.length-1,Math.floor(elapsed/(routine.seconds/routine.steps.length))));if(!remaining){stopMovement();growthMessage('movement-words','Your break is complete. Return at your own pace.');}};tick();movementTimer=setInterval(tick,250);};$('movement-stop').onclick=()=>{stopMovement();growthMessage('movement-words','Break finished.');};
