// Only these explicitly created public fragments are replayed on a language change.
function motiveJournalWord(tag,source,values={}){const node=document.createElement(tag);node.dataset.motiveJournalWord=source;node.dataset.motiveJournalValues=JSON.stringify(values);refreshMotiveJournalWord(node);return node;}
function refreshMotiveJournalWord(node){if(typeof node?.dataset?.motiveJournalWord!=='string')return;const result=appInterface(node.dataset.motiveJournalWord,JSON.parse(node.dataset.motiveJournalValues||'{}'));node.textContent=result.text;node.setAttribute('lang',result.language);}
function motiveJournalPeriod(period){const source={morning:'Morning',evening:'Evening',Reflection:'Reflection','Earlier reflection':'Earlier reflection'};return Object.prototype.hasOwnProperty.call(source,period)?appInterface(source[period]):{text:period||appInterface('Reflection').text,language:period?'en':appInterface('Reflection').language};}
function motiveJournalHeading(node,day,period){if(day)node.append(document.createTextNode(day+' · '));const source={morning:'Morning',evening:'Evening',Reflection:'Reflection','Earlier reflection':'Earlier reflection'};if(Object.prototype.hasOwnProperty.call(source,period)||!period)node.append(motiveJournalWord('span',source[period]||'Reflection'));else{const span=document.createElement('span');span.textContent=period;node.append(span);}return node;}
function motiveJournalCard(entry,trash=false){const card=document.createElement('article');card.className='studio-record';const title=document.createElement('h4');if(trash){if(entry.day)title.append(document.createTextNode(entry.day+' · '));else title.append(motiveJournalWord('span','Earlier moment'),document.createTextNode(' · '));title.append(motiveJournalWord('span','Recovery bin'));}else motiveJournalHeading(title,entry.day,entry.period);card.append(title);if(entry.note){const note=document.createElement('p');note.textContent=entry.note;card.append(note);}else card.append(motiveJournalWord('p',trash?'Photo or voice reflection':'Media reflection'));return card;}
function motiveJournalPublicCard(title,note,values={}){const card=document.createElement('article');card.className='studio-record';card.append(motiveJournalWord('h4',title,values),motiveJournalWord('p',note));return card;}
function motiveJournalAction(source,action){const button=growthButton(source,action);button.dataset.motiveJournalWord=source;button.dataset.motiveJournalValues='{}';refreshMotiveJournalWord(button);return button;}
function motiveJournalMood(entry){const key=entry.key||entry.id;const reviewed=[{id:'low',label:'Low energy',icon:'◒',color:'#a7b5cf'},{id:'scattered',label:'Scattered',icon:'✧',color:'#d4b47c'},{id:'stuck',label:'Stuck',icon:'◈',color:'#c6a7b5'},{id:'curious',label:'Curious',icon:'✳',color:'#83b29c'},{id:'overwhelmed',label:'Overwhelmed',icon:'≈',color:'#b9a0cf'}];const mood=reviewed.find(m=>m.id===key&&m.label===entry.label&&m.icon===entry.icon&&m.color===entry.color);return mood?mood.label:null;}
function journalFilters(){return {query:$('journal-search').value,from:$('journal-from').value,to:$('journal-to').value};}
async function journalEntries(includeTrash=false){if(studioPrefs.vault&&!vaultKey)throw Error('Unlock your journal first.');const version=vaultSessionVersion;const entries=[];if(!includeTrash)for(const [day,e]of Object.entries(state.companion.journal))if(e.note)entries.push({day,note:e.note,period:'Earlier reflection',legacy:true});for(const row of studioRecords.filter(r=>r.kind==='journal'&&!!r.deleted===includeTrash).sort((a,b)=>b.updated-a.updated)){if(!row.payload&&!row.encrypted)continue;const payload=row.encrypted?await unseal(row.encrypted,vaultKey):row.payload;if(version!==vaultSessionVersion||studioPrefs.vault&&!vaultKey)throw Error('Journal locked.');entries.push({...payload,row});}return MG.search(entries,journalFilters());}
renderJournal=async function(){const version=++journalRenderVersion;updatePrompt();$('studio-trends').replaceChildren();const recent=moodEntries().slice(-7);for(const e of recent){const li=document.createElement('li');li.append(document.createTextNode(e.day+' '+e.icon+' '));const mood=motiveJournalMood(e);if(mood)li.append(motiveJournalWord('span',mood));else li.append(document.createTextNode(e.label));$('studio-trends').append(li);}const locked=!!studioPrefs.vault&&!vaultKey;$('journal-editor').hidden=locked;$('vault-locked').hidden=!locked;$('journal-list').replaceChildren();if(studioPrefs.vault&&!vaultKey){growthMessage('journal-search-status','Unlock your journal to search, restore, or export.');return;}try{const trash=$('journal-trash').checked;const entries=await journalEntries(trash);if(version!==journalRenderVersion||studioPrefs.vault&&!vaultKey)return;for(const e of entries.slice(0,(journalPage+1)*30)){let card;if(trash){card=motiveJournalCard(e,true);card.append(motiveJournalAction('Restore entry',async()=>{if(studioPrefs.vault&&!vaultKey)throw Error('Unlock your journal first.');await dbWrite([{...e.row,deleted:false,updated:Date.now()}]);await renderJournal();}),motiveJournalAction('Permanently remove content',async()=>{if(studioPrefs.vault&&!vaultKey)throw Error('Unlock your journal first.');if(!window.confirm(appInterface('Permanently remove this entry? It cannot be restored from this device.').text))return;await dbWrite([{id:e.row.id,kind:'journal',deleted:true,updated:Date.now()}]);await renderJournal();}));}else if(e.row)card=recordElement(e.row,e);else card=motiveJournalCard(e);$('journal-list').append(card);}growthMessage('journal-search-status',entries.length+' matching '+(trash?'recoverable deleted entries':'moments'));$('journal-more').hidden=entries.length<=(journalPage+1)*30;}catch(e){growthMessage('journal-search-status',e.message);}};
for(const id of ['journal-search','journal-from','journal-to','journal-trash'])$(id).oninput=()=>{journalPage=0;renderJournal();};$('journal-trash').onchange=()=>{journalPage=0;renderJournal();};$('journal-more').onclick=()=>{journalPage++;renderJournal();};
$('journal-csv').onclick=async()=>{try{const version=vaultSessionVersion;const entries=await journalEntries($('journal-trash').checked);if(version!==vaultSessionVersion||studioPrefs.vault&&!vaultKey)throw Error('Journal locked.');downloadFile(new Blob([MG.csv([['Date','Moment','Reflection'].map(source=>appInterface(source).text),...entries.map(e=>[e.day,motiveJournalPeriod(e.period).text,e.note])])],{type:'text/csv;charset=utf-8'}),'motive-journal-'+dayDate()+'.csv');growthMessage('journal-search-status','Readable CSV downloaded.');}catch(e){growthMessage('journal-search-status',e.message);}};
function clearPrintJournal(){document.getElementById('motive-print-journal')?.remove();document.body.classList.remove('printing-journal');}
$('journal-print').onclick=async()=>{try{const version=vaultSessionVersion;const entries=await journalEntries($('journal-trash').checked);if(version!==vaultSessionVersion||studioPrefs.vault&&!vaultKey)throw Error('Journal locked.');clearPrintJournal();const print=document.createElement('section');print.id='motive-print-journal';const heading=document.createElement('article');heading.className='studio-record';heading.append(motiveJournalWord('h4','Motive · my moments'));const date=document.createElement('p');date.textContent=dayDate();heading.append(date);print.append(heading);for(const e of entries)print.append(motiveJournalCard(e));document.body.append(print);document.body.classList.add('printing-journal');window.print();}catch(e){growthMessage('journal-search-status',e.message);}};
window.addEventListener('afterprint',clearPrintJournal);
const originalLockJournal=lockJournal;lockJournal=function(){journalRenderVersion++;clearPrintJournal();originalLockJournal();growthMessage('journal-search-status','Journal locked.');};
const originalDeleteRecord=deleteRecord;deleteRecord=function(row){if(row.kind!=='journal')return originalDeleteRecord(row);return async()=>{try{if(studioPrefs.vault&&!vaultKey)throw Error('Unlock your journal first.');await dbWrite([{...row,deleted:true,updated:Date.now()}]);await renderJournal();}catch(e){toast(e.message);}};};

// Optional vibration is a capability, not a promise of Safari support.
const hapticLabel=document.createElement('label');hapticLabel.innerHTML='<input type="checkbox" id="session-haptics"> Gentle vibration at breathing changes (supported devices)';$('session-sound').after(hapticLabel);
let lastHapticPhase='';const originalRenderSession=renderSession;renderSession=function(){originalRenderSession();if(!sessionRun?.running){lastHapticPhase='';return;}const phase=WB.frame(sessionRun.kind,sessionElapsed(),sessionRun.total,sessionRun.natural).phase;if($('session-haptics').checked&&phase!=='natural'&&phase!==lastHapticPhase&&typeof navigator.vibrate==='function')navigator.vibrate(30);lastHapticPhase=phase;};
$('session-haptics').disabled=typeof navigator.vibrate!=='function';if($('session-haptics').disabled)hapticLabel.title='This browser does not support vibration. iPhone Safari does not provide this API.';
const originalSessionStart=$('session-start').onclick;$('session-start').onclick=async()=>{if($('session-kind').value==='daily')WB.sessions.daily=MG.dailyMeditation(dayDate());lastHapticPhase='';return originalSessionStart();};
